content.content:
1	import { useState, useEffect, useMemo, useCallback } from "react";
2	import { supabase } from "@/integrations/supabase/client";
3	import { toast } from "sonner";
4	import { Button } from "@/shared/ui/button";
5	import { Input } from "@/shared/ui/input";
6	import { Badge } from "@/shared/ui/badge";
7	import { GlassCard } from "@/shared/ui/glass-card";
8	import {
9	  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
10	} from "@/shared/ui/table";
11	import { Search, Phone, Download, Loader2, Building2, ArrowUp, ArrowDown } from "lucide-react";
12	import { cn } from "@/shared/lib/utils";
13	import * as XLSX from "xlsx";
14	
15	interface NotaRow {
16	  id: number;
17	  numero_nota: string | null;
18	  fornecedor: string | null;
19	  cnpj_emitente: string | null;
20	  endereco_emitente: string | null;
21	  data_nota: string | null;
22	  data_vencimento: string | null;
23	  valor_total: number | null;
24	}
25	
26	interface FornecedorRegistro {
27	  cnpj: string;
28	  telefone: string | null;
29	  endereco: string | null;
30	}
31	
32	interface PagamentoRow {
33	  nota_fiscal_id: number | null;
34	  status: string | null;
35	  data_pagamento: string | null;
36	}
37	
38	type PayStatus = "pago" | "a_pagar" | "vencida" | "sem_vencimento" | "sem_link";
39	
40	interface PlanilhaRow {
41	  notaId: number;
42	  numeroNota: string;
43	  fornecedor: string;
44	  cnpj: string | null;
45	  endereco: string | null;
46	  telefone: string | null;
47	  dataEmissao: string | null;
48	  dataVencimento: string | null;
49	  prazoEmDias: number | null;
50	  diasVsHoje: number | null;
51	  valor: number;
52	  payStatus: PayStatus;
53	  dataPagamento: string | null;
54	}
55	
56	type SortKey = "fornecedor" | "cnpj" | "emissao" | "vencimento" | "prazo" | "valor" | "status";
57	type SortDir = "asc" | "desc";
58	
59	function formatCnpj(cnpj: string | null | undefined): string {
60	  if (!cnpj) return "—";
61	  const d = cnpj.replace(/\D/g, "");
62	  if (d.length !== 14) return cnpj;
63	  return `${d.slice(0, 2)}.${d.slice(2, 5)}.${d.slice(5, 8)}/${d.slice(8, 12)}-${d.slice(12)}`;
64	}
65	
66	function formatDateBR(iso: string | null | undefined): string {
67	  if (!iso) return "—";
68	  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(iso);
69	  if (!m) return iso;
70	  return `${m[3]}/${m[2]}/${m[1]}`;
71	}
72	
73	function brl(v: number): string {
74	  return v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
75	}
76	
77	function diffDays(fromIso: string, toIso: string): number {
78	  const f = new Date(`${fromIso}T12:00:00`).getTime();
79	  const t = new Date(`${toIso}T12:00:00`).getTime();
80	  return Math.round((t - f) / (1000 * 60 * 60 * 24));
81	}
82	
83	const PAY_RANK: Record<PayStatus, number> = {
84	  vencida: 0, a_pagar: 1, sem_vencimento: 2, pago: 3, sem_link: 4,
85	};
86	
87	export const FornecedoresPanel = () => {
88	  const [notas, setNotas] = useState<NotaRow[]>([]);
89	  const [pagamentos, setPagamentos] = useState<PagamentoRow[]>([]);
90	  const [registros, setRegistros] = useState<Record<string, FornecedorRegistro>>({});
91	  const [loading, setLoading] = useState(false);
92	  const [search, setSearch] = useState("");
93	  const [phoneEdits, setPhoneEdits] = useState<Record<string, string>>({});
94	  const [savingPhone, setSavingPhone] = useState<string | null>(null);
95	  const [sortKey, setSortKey] = useState<SortKey>("vencimento");
96	  const [sortDir, setSortDir] = useState<SortDir>("asc");
97	
98	  const todayStr = useMemo(() => {
99	    const d = new Date();
100	    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
101	  }, []);
102	
103	  const loadData = useCallback(async () => {
104	    setLoading(true);
105	    try {
106	      const notasQ = supabase
107	        .from("notas_fiscais")
108	        .select("id, numero_nota, fornecedor, cnpj_emitente, endereco_emitente, data_nota, data_vencimento, valor_total")
109	        .not("fornecedor", "ilike", "%momma doces%")
110	        .order("data_nota", { ascending: false, nullsFirst: false });
111	
112	      const fornQ = supabase.from("fornecedores").select("cnpj, telefone, endereco");
113	      const pagQ = supabase
114	        .from("contas_pagar_receber")
115	        .select("nota_fiscal_id, status, data_pagamento")
116	        .not("nota_fiscal_id", "is", null);
117	
118	      const [{ data: notasData, error: notasErr }, { data: fornData, error: fornErr }, { data: pagData, error: pagErr }]
119	        = await Promise.all([notasQ, fornQ, pagQ]);
120	
121	      if (notasErr) throw notasErr;
122	      if (fornErr) throw fornErr;
123	      if (pagErr) throw pagErr;
124	
125	      setNotas((notasData || []) as NotaRow[]);
126	      setPagamentos((pagData || []) as PagamentoRow[]);
127	      const regMap: Record<string, FornecedorRegistro> = {};
128	      (fornData || []).forEach((f: any) => {
129	        regMap[f.cnpj] = { cnpj: f.cnpj, telefone: f.telefone, endereco: f.endereco };
130	      });
131	      setRegistros(regMap);
132	    } catch (e) {
133	      console.error(e);
134	      toast.error("Erro ao carregar planilha de fornecedores.");
135	    } finally {
136	      setLoading(false);
137	    }
138	  }, []);
139	
140	  useEffect(() => {
141	    loadData();
142	  }, [loadData]);
143	
144	  const pagByNotaId = useMemo(() => {
145	    const m: Record<number, PagamentoRow> = {};
146	    pagamentos.forEach((p) => {
147	      if (p.nota_fiscal_id != null) m[p.nota_fiscal_id] = p;
148	    });
149	    return m;
150	  }, [pagamentos]);
151	
152	  const rows: PlanilhaRow[] = useMemo(() => {
153	    return notas.map((n) => {
154	      const cnpjDigits = (n.cnpj_emitente || "").replace(/\D/g, "");
155	      const cnpj = cnpjDigits.length === 14 ? cnpjDigits : null;
156	      const registro = cnpj ? registros[cnpj] : undefined;
157	      const pag = pagByNotaId[n.id];
158	
159	      let payStatus: PayStatus;
160	      let dataPagamento: string | null = null;
161	      if (pag) {
162	        if (pag.status === "pago") {
163	          payStatus = "pago";
164	          dataPagamento = pag.data_pagamento;
165	        } else if (n.data_vencimento && n.data_vencimento < todayStr) {
166	          payStatus = "vencida";
167	        } else {
168	          payStatus = "a_pagar";
169	        }
170	      } else {
171	        payStatus = n.data_vencimento ? "a_pagar" : "sem_vencimento";
172	      }
173	
174	      const prazo = n.data_nota && n.data_vencimento
175	        ? diffDays(n.data_nota, n.data_vencimento)
176	        : null;
177	      const diasVsHoje = n.data_vencimento ? diffDays(todayStr, n.data_vencimento) : null;
178	
179	      return {
180	        notaId: n.id,
181	        numeroNota: n.numero_nota || "—",
182	        fornecedor: n.fornecedor || "(sem nome)",
183	        cnpj,
184	        endereco: registro?.endereco || n.endereco_emitente || null,
185	        telefone: registro?.telefone || null,
186	        dataEmissao: n.data_nota,
187	        dataVencimento: n.data_vencimento,
188	        prazoEmDias: prazo,
189	        diasVsHoje,
190	        valor: Number(n.valor_total) || 0,
191	        payStatus,
192	        dataPagamento,
193	      };
194	    });
195	  }, [notas, pagByNotaId, registros, todayStr]);
196	
197	  const filtered = useMemo(() => {
198	    const base = !search.trim() ? rows : (() => {
199	      const q = search.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");
200	      return rows.filter((r) => {
201	        const haystack = [r.fornecedor, r.cnpj || "", r.endereco || "", r.telefone || "", r.numeroNota]
202	          .join(" ")
203	          .toLowerCase()
204	          .normalize("NFD")
205	          .replace(/[̀-ͯ]/g, "");
206	        return haystack.includes(q);
207	      });
208	    })();
209	
210	    const sorted = [...base].sort((a, b) => {
211	      const dir = sortDir === "asc" ? 1 : -1;
212	      switch (sortKey) {
213	        case "fornecedor": return a.fornecedor.localeCompare(b.fornecedor, "pt-BR") * dir;
214	        case "cnpj":       return ((a.cnpj || "zzz").localeCompare(b.cnpj || "zzz")) * dir;
215	        case "emissao":    return ((a.dataEmissao || "9999").localeCompare(b.dataEmissao || "9999")) * dir;
216	        case "vencimento": return ((a.dataVencimento || "9999").localeCompare(b.dataVencimento || "9999")) * dir;
217	        case "prazo":      return ((a.prazoEmDias ?? 99999) - (b.prazoEmDias ?? 99999)) * dir;
218	        case "valor":      return (a.valor - b.valor) * dir;
219	        case "status":     return (PAY_RANK[a.payStatus] - PAY_RANK[b.payStatus]) * dir;
220	        default: return 0;
221	      }
222	    });
223	    return sorted;
224	  }, [rows, search, sortKey, sortDir]);
225	
226	  const totals = useMemo(() => {
227	    let pago = 0, aPagar = 0, vencida = 0, valorTotal = 0;
228	    filtered.forEach((r) => {
229	      valorTotal += r.valor;
230	      if (r.payStatus === "pago") pago += 1;
231	      else if (r.payStatus === "vencida") vencida += 1;
232	      else if (r.payStatus === "a_pagar") aPagar += 1;
233	    });
234	    return { pago, aPagar, vencida, valorTotal };
235	  }, [filtered]);
236	
237	  const toggleSort = (key: SortKey) => {
238	    if (sortKey === key) setSortDir(sortDir === "asc" ? "desc" : "asc");
239	    else { setSortKey(key); setSortDir("asc"); }
240	  };
241	
242	  const sortIcon = (key: SortKey) => {
243	    if (sortKey !== key) return null;
244	    return sortDir === "asc"
245	      ? <ArrowUp className="inline h-3 w-3 ml-1" />
246	      : <ArrowDown className="inline h-3 w-3 ml-1" />;
247	  };
248	
249	  const savePhone = async (cnpj: string, nome: string, endereco: string | null) => {
250	    const value = (phoneEdits[cnpj] ?? "").trim();
251	    setSavingPhone(cnpj);
252	    try {
253	      const existing = registros[cnpj];
254	      if (existing) {
255	        const { error } = await supabase
256	          .from("fornecedores")
257	          .update({ telefone: value || null })
258	          .eq("cnpj", cnpj);
259	        if (error) throw error;
260	      } else {
261	        const { error } = await supabase.from("fornecedores").insert({
262	          cnpj,
263	          nome,
264	          telefone: value || null,
265	          endereco: endereco || null,
266	        });
267	        if (error) throw error;
268	      }
269	      setRegistros((prev) => ({
270	        ...prev,
271	        [cnpj]: { cnpj, telefone: value || null, endereco: existing?.endereco ?? endereco ?? null },
272	      }));
273	      setPhoneEdits((prev) => {
274	        const next = { ...prev };
275	        delete next[cnpj];
276	        return next;
277	      });
278	      toast.success("Telefone salvo.");
279	    } catch (e) {
280	      console.error(e);
281	      toast.error("Erro ao salvar telefone — verifique sua permissão.");
282	    } finally {
283	      setSavingPhone(null);
284	    }
285	  };
286	
287	  const exportToExcel = () => {
288	    const xlRows = filtered.map((r) => {
289	      const periodo = r.dataEmissao && r.dataVencimento
290	        ? `${formatDateBR(r.dataEmissao)} → ${formatDateBR(r.dataVencimento)}`
291	        : formatDateBR(r.dataEmissao);
292	      return {
293	        Fornecedor: r.fornecedor,
294	        CNPJ: formatCnpj(r.cnpj),
295	        Endereço: r.endereco || "",
296	        Telefone: r.telefone || "",
297	        "NF Número": r.numeroNota,
298	        "Data Emissão": formatDateBR(r.dataEmissao),
299	        "Data Vencimento": formatDateBR(r.dataVencimento),
300	        "Período Pagamento": periodo,
301	        "Prazo (dias)": r.prazoEmDias ?? "",
302	        Valor: r.valor,
303	        "Status Financeiro": (
304	          r.payStatus === "pago" ? `Pago em ${formatDateBR(r.dataPagamento)}`
305	            : r.payStatus === "vencida" ? "Vencida"
306	            : r.payStatus === "a_pagar" ? "A pagar"
307	            : r.payStatus === "sem_vencimento" ? "Sem vencimento"
308	            : "Sem link financeiro"
309	        ),
310	      };
311	    });
312	    const ws = XLSX.utils.json_to_sheet(xlRows);
313	    const wb = XLSX.utils.book_new();
314	    XLSX.utils.book_append_sheet(wb, ws, "Fornecedores");
315	    const ts = new Date().toISOString().slice(0, 10);
316	    XLSX.writeFile(wb, `planilha_fornecedores_${ts}.xlsx`);
317	  };
318	
319	  const statusBadge = (r: PlanilhaRow) => {
320	    if (r.payStatus === "pago") {
321	      return (
322	        <Badge className="bg-emerald-100 text-emerald-800 border-emerald-200 hover:bg-emerald-100">
323	          Pago{r.dataPagamento ? ` em ${formatDateBR(r.dataPagamento)}` : ""}
324	        </Badge>
325	      );
326	    }
327	    if (r.payStatus === "vencida") {
328	      return (
329	        <Badge className="bg-red-100 text-red-800 border-red-200 hover:bg-red-100">
330	          Vencida há {Math.abs(r.diasVsHoje ?? 0)}d
331	        </Badge>
332	      );
333	    }
334	    if (r.payStatus === "a_pagar") {
335	      return (
336	        <Badge className="bg-amber-100 text-amber-800 border-amber-200 hover:bg-amber-100">
337	          {r.diasVsHoje != null ? `A pagar em ${r.diasVsHoje}d` : "A pagar"}
338	        </Badge>
339	      );
340	    }
341	    if (r.payStatus === "sem_vencimento") {
342	      return <Badge variant="outline">Sem vencimento</Badge>;
343	    }
344	    return <Badge variant="outline">Sem link</Badge>;
345	  };
346	
347	  return (
348	    <div className="space-y-4">
349	      <GlassCard className="p-4 sm:p-6">
350	        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
351	          <div className="flex items-center gap-3">
352	            <div className="w-10 h-10 rounded-full bg-[#57715B]/10 flex items-center justify-center">
353	              <Building2 className="h-5 w-5 text-[#57715B]" />
354	            </div>
355	            <div>
356	              <h2 className="text-lg sm:text-xl font-serif text-[#2D362E]">Planilha de Fornecedores</h2>
357	              <p className="text-xs sm:text-sm text-[#57715B]/70">
358	                {filtered.length} NF{filtered.length === 1 ? "" : "s"} · {brl(totals.valorTotal)} · {totals.pago} pago{totals.pago === 1 ? "" : "s"} · {totals.aPagar} a pagar · {totals.vencida} vencida{totals.vencida === 1 ? "" : "s"}
359	              </p>
360	            </div>
361	          </div>
362	          <div className="flex flex-col sm:flex-row gap-2 w-full sm:w-auto">
363	            <div className="relative flex-1 sm:w-72">
364	              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-[#57715B]/50" />
365	              <Input data-mia-field="search"
366	                value={search}
367	                onChange={(e) => setSearch(e.target.value)}
368	                placeholder="Buscar por nome, CNPJ, endereço, NF..."
369	                className="pl-9 rounded-full border-[#57715B]/20"
370	              />
371	            </div>
372	            <Button data-mia-action="export-to-excel"
373	              variant="outline"
374	              onClick={exportToExcel}
375	              disabled={filtered.length === 0}
376	              className="rounded-full border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10"
377	            >
378	              <Download className="mr-2 h-4 w-4" />
379	              Excel
380	            </Button>
381	          </div>
382	        </div>
383	      </GlassCard>
384	
385	      <GlassCard className="p-0 overflow-hidden">
386	        <div className="overflow-x-auto">
387	          <Table className="min-w-[1200px] w-full text-sm">
388	            <TableHeader className="bg-[#57715B]/5">
389	              <TableRow className="hover:bg-transparent border-b border-[#57715B]/10">
390	                <TableHead
391	                  className="font-bold text-[#57715B] uppercase text-xs tracking-wider cursor-pointer"
392	                  onClick={() => toggleSort("fornecedor")}
393	                >
394	                  Fornecedor{sortIcon("fornecedor")}
395	                </TableHead>
396	                <TableHead
397	                  className="w-[170px] font-bold text-[#57715B] uppercase text-xs tracking-wider cursor-pointer"
398	                  onClick={() => toggleSort("cnpj")}
399	                >
400	                  CNPJ{sortIcon("cnpj")}
401	                </TableHead>
402	                <TableHead className="font-bold text-[#57715B] uppercase text-xs tracking-wider">
403	                  Endereço
404	                </TableHead>
405	                <TableHead className="w-[210px] font-bold text-[#57715B] uppercase text-xs tracking-wider">
406	                  Telefone
407	                </TableHead>
408	                <TableHead
409	                  className="w-[210px] font-bold text-[#57715B] uppercase text-xs tracking-wider cursor-pointer"
410	                  onClick={() => toggleSort("vencimento")}
411	                >
412	                  Período Pagamento{sortIcon("vencimento")}
413	                </TableHead>
414	                <TableHead
415	                  className="w-[110px] font-bold text-[#57715B] uppercase text-xs tracking-wider text-right cursor-pointer"
416	                  onClick={() => toggleSort("valor")}
417	                >
418	                  Valor{sortIcon("valor")}
419	                </TableHead>
420	                <TableHead
421	                  className="w-[180px] font-bold text-[#57715B] uppercase text-xs tracking-wider text-center cursor-pointer"
422	                  onClick={() => toggleSort("status")}
423	                >
424	                  Status Financeiro{sortIcon("status")}
425	                </TableHead>
426	              </TableRow>
427	            </TableHeader>
428	            <TableBody>
429	              {loading && (
430	                <TableRow>
431	                  <TableCell colSpan={7} className="h-32 text-center text-muted-foreground">
432	                    <Loader2 className="inline h-5 w-5 animate-spin mr-2" />
433	                    Carregando...
434	                  </TableCell>
435	                </TableRow>
436	              )}
437	              {!loading && filtered.length === 0 && (
438	                <TableRow>
439	                  <TableCell colSpan={7} className="h-32 text-center text-muted-foreground">
440	                    Nenhuma NF encontrada.
441	                  </TableCell>
442	                </TableRow>
443	              )}
444	              {!loading && filtered.map((r) => {
445	                const editValue = r.cnpj
446	                  ? (phoneEdits[r.cnpj] ?? r.telefone ?? "")
447	                  : "";
448	                const dirty = r.cnpj
449	                  && phoneEdits[r.cnpj] != null
450	                  && phoneEdits[r.cnpj] !== (r.telefone ?? "");
451	                const periodo = r.dataEmissao && r.dataVencimento
452	                  ? `${formatDateBR(r.dataEmissao)} → ${formatDateBR(r.dataVencimento)}`
453	                  : (r.dataEmissao ? `${formatDateBR(r.dataEmissao)} → —` : "—");
454	                const prazoTxt = r.prazoEmDias != null ? `${r.prazoEmDias} dia${r.prazoEmDias === 1 ? "" : "s"}` : "";
455	
456	                return (
457	                  <TableRow
458	                    key={r.notaId}
459	                    className="hover:bg-[#57715B]/5 transition-colors border-b border-[#57715B]/5"
460	                  >
461	                    <TableCell className="font-semibold text-[#2D362E]">
462	                      <div className="flex flex-col">
463	                        <span>{r.fornecedor}</span>
464	                        <span className="text-[10px] text-[#57715B]/60 font-normal">NF {r.numeroNota}</span>
465	                      </div>
466	                    </TableCell>
467	                    <TableCell className="text-[#2D362E]/80 font-mono text-xs">
468	                      {formatCnpj(r.cnpj)}
469	                    </TableCell>
470	                    <TableCell className="text-[#2D362E]/70 text-xs max-w-[280px]">
471	                      <span className="line-clamp-2" title={r.endereco || ""}>
472	                        {r.endereco || "—"}
473	                      </span>
474	                    </TableCell>
475	                    <TableCell>
476	                      {r.cnpj ? (
477	                        <div className="flex gap-1.5">
478	                          <div className="relative flex-1">
479	                            <Phone className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-[#57715B]/50" />
480	                            <Input
481	                              value={editValue}
482	                              onChange={(e) => setPhoneEdits((prev) => ({ ...prev, [r.cnpj!]: e.target.value }))}
483	                              placeholder="(00) 00000-0000"
484	                              className="h-8 pl-7 text-xs rounded-md border-[#57715B]/20"
485	                            />
486	                          </div>
487	                          {dirty && (
488	                            <Button
489	                              size="sm"
490	                              onClick={() => savePhone(r.cnpj!, r.fornecedor, r.endereco)}
491	                              disabled={savingPhone === r.cnpj}
492	                              className="h-8 px-3 bg-[#57715B] hover:bg-[#4A614D] text-white text-xs"
493	                            >
494	                              {savingPhone === r.cnpj ? <Loader2 className="h-3 w-3 animate-spin" /> : "Salvar"}
495	                            </Button>
496	                          )}
497	                        </div>
498	                      ) : (
