import { useState, useEffect, useMemo, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Badge } from "@/shared/ui/badge";
import { GlassCard } from "@/shared/ui/glass-card";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/shared/ui/table";
import { Search, Phone, Download, Loader2, Building2, ArrowUp, ArrowDown } from "lucide-react";
import { cn } from "@/shared/lib/utils";
import * as XLSX from "xlsx";

interface NotaRow {
  id: number;
  numero_nota: string | null;
  fornecedor: string | null;
  cnpj_emitente: string | null;
  endereco_emitente: string | null;
  data_nota: string | null;
  data_vencimento: string | null;
  valor_total: number | null;
}

interface FornecedorRegistro {
  cnpj: string;
  telefone: string | null;
  endereco: string | null;
}

interface PagamentoRow {
  nota_fiscal_id: number | null;
  status: string | null;
  data_pagamento: string | null;
}

type PayStatus = "pago" | "a_pagar" | "vencida" | "sem_vencimento" | "sem_link";

interface PlanilhaRow {
  notaId: number;
  numeroNota: string;
  fornecedor: string;
  cnpj: string | null;
  endereco: string | null;
  telefone: string | null;
  dataEmissao: string | null;
  dataVencimento: string | null;
  prazoEmDias: number | null;
  diasVsHoje: number | null;
  valor: number;
  payStatus: PayStatus;
  dataPagamento: string | null;
}

type SortKey = "fornecedor" | "cnpj" | "emissao" | "vencimento" | "prazo" | "valor" | "status";
type SortDir = "asc" | "desc";

function formatCnpj(cnpj: string | null | undefined): string {
  if (!cnpj) return "—";
  const d = cnpj.replace(/\D/g, "");
  if (d.length !== 14) return cnpj;
  return `${d.slice(0, 2)}.${d.slice(2, 5)}.${d.slice(5, 8)}/${d.slice(8, 12)}-${d.slice(12)}`;
}

function formatDateBR(iso: string | null | undefined): string {
  if (!iso) return "—";
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(iso);
  if (!m) return iso;
  return `${m[3]}/${m[2]}/${m[1]}`;
}

function brl(v: number): string {
  return v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

function diffDays(fromIso: string, toIso: string): number {
  const f = new Date(`${fromIso}T12:00:00`).getTime();
  const t = new Date(`${toIso}T12:00:00`).getTime();
  return Math.round((t - f) / (1000 * 60 * 60 * 24));
}

const PAY_RANK: Record<PayStatus, number> = {
  vencida: 0, a_pagar: 1, sem_vencimento: 2, pago: 3, sem_link: 4,
};

export const FornecedoresPanel = () => {
  const [notas, setNotas] = useState<NotaRow[]>([]);
  const [pagamentos, setPagamentos] = useState<PagamentoRow[]>([]);
  const [registros, setRegistros] = useState<Record<string, FornecedorRegistro>>({});
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState("");
  const [phoneEdits, setPhoneEdits] = useState<Record<string, string>>({});
  const [savingPhone, setSavingPhone] = useState<string | null>(null);
  const [sortKey, setSortKey] = useState<SortKey>("vencimento");
  const [sortDir, setSortDir] = useState<SortDir>("asc");

  const todayStr = useMemo(() => {
    const d = new Date();
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  }, []);

  const loadData = useCallback(async () => {
    setLoading(true);
    try {
      const notasQ = supabase
        .from("notas_fiscais")
        .select("id, numero_nota, fornecedor, cnpj_emitente, endereco_emitente, data_nota, data_vencimento, valor_total")
        .not("fornecedor", "ilike", "%momma doces%")
        .order("data_nota", { ascending: false, nullsFirst: false });

      const fornQ = supabase.from("fornecedores").select("cnpj, telefone, endereco");
      const pagQ = supabase
        .from("contas_pagar_receber")
        .select("nota_fiscal_id, status, data_pagamento")
        .not("nota_fiscal_id", "is", null);

      const [{ data: notasData, error: notasErr }, { data: fornData, error: fornErr }, { data: pagData, error: pagErr }]
        = await Promise.all([notasQ, fornQ, pagQ]);

      if (notasErr) throw notasErr;
      if (fornErr) throw fornErr;
      if (pagErr) throw pagErr;

      setNotas((notasData || []) as NotaRow[]);
      setPagamentos((pagData || []) as PagamentoRow[]);
      const regMap: Record<string, FornecedorRegistro> = {};
      (fornData || []).forEach((f: any) => {
        regMap[f.cnpj] = { cnpj: f.cnpj, telefone: f.telefone, endereco: f.endereco };
      });
      setRegistros(regMap);
    } catch (e) {
      console.error(e);
      toast.error("Erro ao carregar planilha de fornecedores.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const pagByNotaId = useMemo(() => {
    const m: Record<number, PagamentoRow> = {};
    pagamentos.forEach((p) => {
      if (p.nota_fiscal_id != null) m[p.nota_fiscal_id] = p;
    });
    return m;
  }, [pagamentos]);

  const rows: PlanilhaRow[] = useMemo(() => {
    return notas.map((n) => {
      const cnpjDigits = (n.cnpj_emitente || "").replace(/\D/g, "");
      const cnpj = cnpjDigits.length === 14 ? cnpjDigits : null;
      const registro = cnpj ? registros[cnpj] : undefined;
      const pag = pagByNotaId[n.id];

      let payStatus: PayStatus;
      let dataPagamento: string | null = null;
      if (pag) {
        if (pag.status === "pago") {
          payStatus = "pago";
          dataPagamento = pag.data_pagamento;
        } else if (n.data_vencimento && n.data_vencimento < todayStr) {
          payStatus = "vencida";
        } else {
          payStatus = "a_pagar";
        }
      } else {
        payStatus = n.data_vencimento ? "a_pagar" : "sem_vencimento";
      }

      const prazo = n.data_nota && n.data_vencimento
        ? diffDays(n.data_nota, n.data_vencimento)
        : null;
      const diasVsHoje = n.data_vencimento ? diffDays(todayStr, n.data_vencimento) : null;

      return {
        notaId: n.id,
        numeroNota: n.numero_nota || "—",
        fornecedor: n.fornecedor || "(sem nome)",
        cnpj,
        endereco: registro?.endereco || n.endereco_emitente || null,
        telefone: registro?.telefone || null,
        dataEmissao: n.data_nota,
        dataVencimento: n.data_vencimento,
        prazoEmDias: prazo,
        diasVsHoje,
        valor: Number(n.valor_total) || 0,
        payStatus,
        dataPagamento,
      };
    });
  }, [notas, pagByNotaId, registros, todayStr]);

  const filtered = useMemo(() => {
    const base = !search.trim() ? rows : (() => {
      const q = search.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");
      return rows.filter((r) => {
        const haystack = [r.fornecedor, r.cnpj || "", r.endereco || "", r.telefone || "", r.numeroNota]
          .join(" ")
          .toLowerCase()
          .normalize("NFD")
          .replace(/[̀-ͯ]/g, "");
        return haystack.includes(q);
      });
    })();

    const sorted = [...base].sort((a, b) => {
      const dir = sortDir === "asc" ? 1 : -1;
      switch (sortKey) {
        case "fornecedor": return a.fornecedor.localeCompare(b.fornecedor, "pt-BR") * dir;
        case "cnpj":       return ((a.cnpj || "zzz").localeCompare(b.cnpj || "zzz")) * dir;
        case "emissao":    return ((a.dataEmissao || "9999").localeCompare(b.dataEmissao || "9999")) * dir;
        case "vencimento": return ((a.dataVencimento || "9999").localeCompare(b.dataVencimento || "9999")) * dir;
        case "prazo":      return ((a.prazoEmDias ?? 99999) - (b.prazoEmDias ?? 99999)) * dir;
        case "valor":      return (a.valor - b.valor) * dir;
        case "status":     return (PAY_RANK[a.payStatus] - PAY_RANK[b.payStatus]) * dir;
        default: return 0;
      }
    });
    return sorted;
  }, [rows, search, sortKey, sortDir]);

  const totals = useMemo(() => {
    let pago = 0, aPagar = 0, vencida = 0, valorTotal = 0;
    filtered.forEach((r) => {
      valorTotal += r.valor;
      if (r.payStatus === "pago") pago += 1;
      else if (r.payStatus === "vencida") vencida += 1;
      else if (r.payStatus === "a_pagar") aPagar += 1;
    });
    return { pago, aPagar, vencida, valorTotal };
  }, [filtered]);

  const toggleSort = (key: SortKey) => {
    if (sortKey === key) setSortDir(sortDir === "asc" ? "desc" : "asc");
    else { setSortKey(key); setSortDir("asc"); }
  };

  const sortIcon = (key: SortKey) => {
    if (sortKey !== key) return null;
    return sortDir === "asc"
      ? <ArrowUp className="inline h-3 w-3 ml-1" />
      : <ArrowDown className="inline h-3 w-3 ml-1" />;
  };

  const savePhone = async (cnpj: string, nome: string, endereco: string | null) => {
    const value = (phoneEdits[cnpj] ?? "").trim();
    setSavingPhone(cnpj);
    try {
      const existing = registros[cnpj];
      if (existing) {
        const { error } = await supabase
          .from("fornecedores")
          .update({ telefone: value || null })
          .eq("cnpj", cnpj);
        if (error) throw error;
      } else {
        const { error } = await supabase.from("fornecedores").insert({
          cnpj,
          nome,
          telefone: value || null,
          endereco: endereco || null,
        });
        if (error) throw error;
      }
      setRegistros((prev) => ({
        ...prev,
        [cnpj]: { cnpj, telefone: value || null, endereco: existing?.endereco ?? endereco ?? null },
      }));
      setPhoneEdits((prev) => {
        const next = { ...prev };
        delete next[cnpj];
        return next;
      });
      toast.success("Telefone salvo.");
    } catch (e) {
      console.error(e);
      toast.error("Erro ao salvar telefone — verifique sua permissão.");
    } finally {
      setSavingPhone(null);
    }
  };

  const exportToExcel = () => {
    const xlRows = filtered.map((r) => {
      const periodo = r.dataEmissao && r.dataVencimento
        ? `${formatDateBR(r.dataEmissao)} → ${formatDateBR(r.dataVencimento)}`
        : formatDateBR(r.dataEmissao);
      return {
        Fornecedor: r.fornecedor,
        CNPJ: formatCnpj(r.cnpj),
        Endereço: r.endereco || "",
        Telefone: r.telefone || "",
        "NF Número": r.numeroNota,
        "Data Emissão": formatDateBR(r.dataEmissao),
        "Data Vencimento": formatDateBR(r.dataVencimento),
        "Período Pagamento": periodo,
        "Prazo (dias)": r.prazoEmDias ?? "",
        Valor: r.valor,
        "Status Financeiro": (
          r.payStatus === "pago" ? `Pago em ${formatDateBR(r.dataPagamento)}`
            : r.payStatus === "vencida" ? "Vencida"
            : r.payStatus === "a_pagar" ? "A pagar"
            : r.payStatus === "sem_vencimento" ? "Sem vencimento"
            : "Sem link financeiro"
        ),
      };
    });
    const ws = XLSX.utils.json_to_sheet(xlRows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Fornecedores");
    const ts = new Date().toISOString().slice(0, 10);
    XLSX.writeFile(wb, `planilha_fornecedores_${ts}.xlsx`);
  };

  const statusBadge = (r: PlanilhaRow) => {
    if (r.payStatus === "pago") {
      return (
        <Badge className="bg-emerald-100 text-emerald-800 border-emerald-200 hover:bg-emerald-100">
          Pago{r.dataPagamento ? ` em ${formatDateBR(r.dataPagamento)}` : ""}
        </Badge>
      );
    }
    if (r.payStatus === "vencida") {
      return (
        <Badge className="bg-red-100 text-red-800 border-red-200 hover:bg-red-100">
          Vencida há {Math.abs(r.diasVsHoje ?? 0)}d
        </Badge>
      );
    }
    if (r.payStatus === "a_pagar") {
      return (
        <Badge className="bg-amber-100 text-amber-800 border-amber-200 hover:bg-amber-100">
          {r.diasVsHoje != null ? `A pagar em ${r.diasVsHoje}d` : "A pagar"}
        </Badge>
      );
    }
    if (r.payStatus === "sem_vencimento") {
      return <Badge variant="outline">Sem vencimento</Badge>;
    }
    return <Badge variant="outline">Sem link</Badge>;
  };

  return (
    <div className="space-y-4">
      <GlassCard className="p-4 sm:p-6">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-[#57715B]/10 flex items-center justify-center">
              <Building2 className="h-5 w-5 text-[#57715B]" />
            </div>
            <div>
              <h2 className="text-lg sm:text-xl font-serif text-[#2D362E]">Planilha de Fornecedores</h2>
              <p className="text-xs sm:text-sm text-[#57715B]/70">
                {filtered.length} NF{filtered.length === 1 ? "" : "s"} · {brl(totals.valorTotal)} · {totals.pago} pago{totals.pago === 1 ? "" : "s"} · {totals.aPagar} a pagar · {totals.vencida} vencida{totals.vencida === 1 ? "" : "s"}
              </p>
            </div>
          </div>
          <div className="flex flex-col sm:flex-row gap-2 w-full sm:w-auto">
            <div className="relative flex-1 sm:w-72">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-[#57715B]/50" />
              <Input data-mia-field="search"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Buscar por nome, CNPJ, endereço, NF..."
                className="pl-9 rounded-full border-[#57715B]/20"
              />
            </div>
            <Button data-mia-action="export-to-excel"
              variant="outline"
              onClick={exportToExcel}
              disabled={filtered.length === 0}
              className="rounded-full border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10"
            >
              <Download className="mr-2 h-4 w-4" />
              Excel
            </Button>
          </div>
        </div>
      </GlassCard>

      <GlassCard className="p-0 overflow-hidden">
        <div className="overflow-x-auto">
          <Table className="min-w-[1200px] w-full text-sm">
            <TableHeader className="bg-[#57715B]/5">
              <TableRow className="hover:bg-transparent border-b border-[#57715B]/10">
                <TableHead
                  className="font-bold text-[#57715B] uppercase text-xs tracking-wider cursor-pointer"
                  onClick={() => toggleSort("fornecedor")}
                >
                  Fornecedor{sortIcon("fornecedor")}
                </TableHead>
                <TableHead
                  className="w-[170px] font-bold text-[#57715B] uppercase text-xs tracking-wider cursor-pointer"
                  onClick={() => toggleSort("cnpj")}
                >
                  CNPJ{sortIcon("cnpj")}
                </TableHead>
                <TableHead className="font-bold text-[#57715B] uppercase text-xs tracking-wider">
                  Endereço
                </TableHead>
                <TableHead className="w-[210px] font-bold text-[#57715B] uppercase text-xs tracking-wider">
                  Telefone
                </TableHead>
                <TableHead
                  className="w-[210px] font-bold text-[#57715B] uppercase text-xs tracking-wider cursor-pointer"
                  onClick={() => toggleSort("vencimento")}
                >
                  Período Pagamento{sortIcon("vencimento")}
                </TableHead>
                <TableHead
                  className="w-[110px] font-bold text-[#57715B] uppercase text-xs tracking-wider text-right cursor-pointer"
                  onClick={() => toggleSort("valor")}
                >
                  Valor{sortIcon("valor")}
                </TableHead>
                <TableHead
                  className="w-[180px] font-bold text-[#57715B] uppercase text-xs tracking-wider text-center cursor-pointer"
                  onClick={() => toggleSort("status")}
                >
                  Status Financeiro{sortIcon("status")}
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading && (
                <TableRow>
                  <TableCell colSpan={7} className="h-32 text-center text-muted-foreground">
                    <Loader2 className="inline h-5 w-5 animate-spin mr-2" />
                    Carregando...
                  </TableCell>
                </TableRow>
              )}
              {!loading && filtered.length === 0 && (
                <TableRow>
                  <TableCell colSpan={7} className="h-32 text-center text-muted-foreground">
                    Nenhuma NF encontrada.
                  </TableCell>
                </TableRow>
              )}
              {!loading && filtered.map((r) => {
                const editValue = r.cnpj
                  ? (phoneEdits[r.cnpj] ?? r.telefone ?? "")
                  : "";
                const dirty = r.cnpj
                  && phoneEdits[r.cnpj] != null
                  && phoneEdits[r.cnpj] !== (r.telefone ?? "");
                const periodo = r.dataEmissao && r.dataVencimento
                  ? `${formatDateBR(r.dataEmissao)} → ${formatDateBR(r.dataVencimento)}`
                  : (r.dataEmissao ? `${formatDateBR(r.dataEmissao)} → —` : "—");
                const prazoTxt = r.prazoEmDias != null ? `${r.prazoEmDias} dia${r.prazoEmDias === 1 ? "" : "s"}` : "";

                return (
                  <TableRow
                    key={r.notaId}
                    className="hover:bg-[#57715B]/5 transition-colors border-b border-[#57715B]/5"
                  >
                    <TableCell className="font-semibold text-[#2D362E]">
                      <div className="flex flex-col">
                        <span>{r.fornecedor}</span>
                        <span className="text-[10px] text-[#57715B]/60 font-normal">NF {r.numeroNota}</span>
                      </div>
                    </TableCell>
                    <TableCell className="text-[#2D362E]/80 font-mono text-xs">
                      {formatCnpj(r.cnpj)}
                    </TableCell>
                    <TableCell className="text-[#2D362E]/70 text-xs max-w-[280px]">
                      <span className="line-clamp-2" title={r.endereco || ""}>
                        {r.endereco || "—"}
                      </span>
                    </TableCell>
                    <TableCell>
                      {r.cnpj ? (
                        <div className="flex gap-1.5">
                          <div className="relative flex-1">
                            <Phone className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-[#57715B]/50" />
                            <Input
                              value={editValue}
                              onChange={(e) => setPhoneEdits((prev) => ({ ...prev, [r.cnpj!]: e.target.value }))}
                              placeholder="(00) 00000-0000"
                              className="h-8 pl-7 text-xs rounded-md border-[#57715B]/20"
                            />
                          </div>
                          {dirty && (
                            <Button
                              size="sm"
                              onClick={() => savePhone(r.cnpj!, r.fornecedor, r.endereco)}
                              disabled={savingPhone === r.cnpj}
                              className="h-8 px-3 bg-[#57715B] hover:bg-[#4A614D] text-white text-xs"
                            >
                              {savingPhone === r.cnpj ? <Loader2 className="h-3 w-3 animate-spin" /> : "Salvar"}
                            </Button>
                          )}
                        </div>
                      ) : (
                        <span className="text-xs text-[#57715B]/50 italic">Edite a NF e adicione o CNPJ pra registrar telefone</span>
                      )}
                    </TableCell>
                    <TableCell className="text-xs">
                      <div className="flex flex-col">
                        <span className="text-[#2D362E]">{periodo}</span>
                        {prazoTxt && (
                          <span className="text-[10px] font-medium text-[#57715B]/70">
                            {prazoTxt}
                          </span>
                        )}
                      </div>
                    </TableCell>
                    <TableCell className="text-right font-bold text-[#2D362E]">{brl(r.valor)}</TableCell>
                    <TableCell className="text-center">{statusBadge(r)}</TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </div>
      </GlassCard>
    </div>
  );
};

