import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Label } from "@/shared/ui/label";
import { Badge } from "@/shared/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/shared/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/ui/tabs";
import {
  Building2,
  Loader2,
  Plus,
  Trash2,
  CheckCircle2,
  Circle,
  Star,
} from "lucide-react";
import { cn } from "@/shared/lib/utils";

export interface Fornecedor {
  cnpj: string;
  nome: string;
  email: string | null;
  telefone: string | null;
  endereco: string | null;
  website: string | null;
  responsavel_comercial: string | null;
  lead_time_dias_uteis: number | null;
  status: "ativo" | "em_homologacao" | "inativo" | "suspenso";
  produtos_fornecidos: { nome: string; unidade: string }[];
  tabela_precos: { produto: string; unidade: string; preco: number; vigencia_ate: string }[];
  homologacao_checklist: {
    referencias_comerciais: boolean;
    pedido_teste: boolean;
    avaliacao_qualidade: boolean;
    acordo_formalizado: boolean;
    cadastro_sistema: boolean;
  };
  avaliacao_desempenho: number | null;
  observacoes: string | null;
  homologado_em: string | null;
  created_at?: string;
  updated_at?: string;
}

const CHECKLIST_ITEMS: { key: keyof Fornecedor["homologacao_checklist"]; label: string; desc: string }[] = [
  { key: "referencias_comerciais", label: "2 referências comerciais", desc: "Solicitar e verificar referências ou histórico de fornecimento" },
  { key: "pedido_teste", label: "Pedido-teste realizado", desc: "Quantidade reduzida (20–30% da demanda habitual)" },
  { key: "avaliacao_qualidade", label: "Avaliação de qualidade", desc: "Prazo de entrega, qualidade do produto, documentação fiscal e atendimento" },
  { key: "acordo_formalizado", label: "Acordo formalizado por escrito", desc: "Preço, prazo e condições de pagamento acordados" },
  { key: "cadastro_sistema", label: "Cadastrado no sistema", desc: "Cadastro completo antes de qualquer pedido" },
];

const emptyForm = (): Omit<Fornecedor, "created_at" | "updated_at" | "homologado_em"> => ({
  cnpj: "",
  nome: "",
  email: null,
  telefone: null,
  endereco: null,
  website: null,
  responsavel_comercial: null,
  lead_time_dias_uteis: null,
  status: "em_homologacao",
  produtos_fornecidos: [],
  tabela_precos: [],
  homologacao_checklist: {
    referencias_comerciais: false,
    pedido_teste: false,
    avaliacao_qualidade: false,
    acordo_formalizado: false,
    cadastro_sistema: false,
  },
  avaliacao_desempenho: null,
  observacoes: null,
});

function formatCnpj(raw: string): string {
  const d = raw.replace(/\D/g, "").slice(0, 14);
  if (d.length <= 2) return d;
  if (d.length <= 5) return `${d.slice(0, 2)}.${d.slice(2)}`;
  if (d.length <= 8) return `${d.slice(0, 2)}.${d.slice(2, 5)}.${d.slice(5)}`;
  if (d.length <= 12) return `${d.slice(0, 2)}.${d.slice(2, 5)}.${d.slice(5, 8)}/${d.slice(8)}`;
  return `${d.slice(0, 2)}.${d.slice(2, 5)}.${d.slice(5, 8)}/${d.slice(8, 12)}-${d.slice(12)}`;
}

interface Props {
  open: boolean;
  onClose: () => void;
  editingFornecedor: Fornecedor | null;
  onSaved: () => void;
}

export const FornecedorModal = ({ open, onClose, editingFornecedor, onSaved }: Props) => {
  const [form, setForm] = useState(emptyForm());
  const [saving, setSaving] = useState(false);
  const [newProduto, setNewProduto] = useState({ nome: "", unidade: "" });
  const [newPreco, setNewPreco] = useState({ produto: "", unidade: "", preco: "", vigencia_ate: "" });

  useEffect(() => {
    if (editingFornecedor) {
      setForm({
        cnpj: editingFornecedor.cnpj,
        nome: editingFornecedor.nome,
        email: editingFornecedor.email,
        telefone: editingFornecedor.telefone,
        endereco: editingFornecedor.endereco,
        website: editingFornecedor.website,
        responsavel_comercial: editingFornecedor.responsavel_comercial,
        lead_time_dias_uteis: editingFornecedor.lead_time_dias_uteis,
        status: editingFornecedor.status,
        produtos_fornecidos: editingFornecedor.produtos_fornecidos ?? [],
        tabela_precos: editingFornecedor.tabela_precos ?? [],
        homologacao_checklist: editingFornecedor.homologacao_checklist ?? emptyForm().homologacao_checklist,
        avaliacao_desempenho: editingFornecedor.avaliacao_desempenho,
        observacoes: editingFornecedor.observacoes,
      });
    } else {
      setForm(emptyForm());
    }
  }, [editingFornecedor, open]);

  const allChecked = Object.values(form.homologacao_checklist).every(Boolean);

  const toggleChecklist = (key: keyof Fornecedor["homologacao_checklist"]) => {
    setForm((prev) => {
      const updated = { ...prev.homologacao_checklist, [key]: !prev.homologacao_checklist[key] };
      const allDone = Object.values(updated).every(Boolean);
      return {
        ...prev,
        homologacao_checklist: updated,
        status: allDone ? "ativo" : prev.status === "ativo" ? "em_homologacao" : prev.status,
      };
    });
  };

  const handleSave = async () => {
    if (!form.cnpj.replace(/\D/g, "") || !form.nome.trim()) {
      toast.error("CNPJ e Razão Social são obrigatórios.");
      return;
    }
    const cnpjDigits = form.cnpj.replace(/\D/g, "");
    if (cnpjDigits.length !== 14) {
      toast.error("CNPJ inválido — deve ter 14 dígitos.");
      return;
    }

    setSaving(true);
    try {
      const payload = {
        cnpj: cnpjDigits,
        nome: form.nome.trim(),
        email: form.email?.trim() || null,
        telefone: form.telefone?.trim() || null,
        endereco: form.endereco?.trim() || null,
        website: form.website?.trim() || null,
        responsavel_comercial: form.responsavel_comercial?.trim() || null,
        lead_time_dias_uteis: form.lead_time_dias_uteis || null,
        status: form.status,
        produtos_fornecidos: form.produtos_fornecidos,
        tabela_precos: form.tabela_precos,
        homologacao_checklist: form.homologacao_checklist,
        avaliacao_desempenho: form.avaliacao_desempenho || null,
        observacoes: form.observacoes?.trim() || null,
        ...(allChecked && !editingFornecedor?.homologado_em ? { homologado_em: new Date().toISOString() } : {}),
      };

      if (editingFornecedor) {
        const { error } = await supabase.from("fornecedores").update(payload).eq("cnpj", cnpjDigits);
        if (error) throw error;
        toast.success("Fornecedor atualizado.");
      } else {
        const { error } = await supabase.from("fornecedores").insert(payload);
        if (error) throw error;
        toast.success("Fornecedor cadastrado.");
      }

      onSaved();
      onClose();
    } catch (e: any) {
      console.error(e);
      if (e?.code === "23505") toast.error("CNPJ já cadastrado.");
      else toast.error("Erro ao salvar fornecedor.");
    } finally {
      setSaving(false);
    }
  };

  const addProduto = () => {
    if (!newProduto.nome.trim()) return;
    setForm((p) => ({ ...p, produtos_fornecidos: [...p.produtos_fornecidos, { nome: newProduto.nome.trim(), unidade: newProduto.unidade.trim() || "un" }] }));
    setNewProduto({ nome: "", unidade: "" });
  };

  const removeProduto = (i: number) => {
    setForm((p) => ({ ...p, produtos_fornecidos: p.produtos_fornecidos.filter((_, idx) => idx !== i) }));
  };

  const addPreco = () => {
    if (!newPreco.produto.trim() || !newPreco.preco) return;
    setForm((p) => ({
      ...p,
      tabela_precos: [...p.tabela_precos, {
        produto: newPreco.produto.trim(),
        unidade: newPreco.unidade.trim() || "un",
        preco: parseFloat(newPreco.preco),
        vigencia_ate: newPreco.vigencia_ate || "",
      }],
    }));
    setNewPreco({ produto: "", unidade: "", preco: "", vigencia_ate: "" });
  };

  const removePreco = (i: number) => {
    setForm((p) => ({ ...p, tabela_precos: p.tabela_precos.filter((_, idx) => idx !== i) }));
  };

  const field = (value: string | null, onChange: (v: string) => void, placeholder: string, type = "text") => (
    <Input
      type={type}
      value={value ?? ""}
      onChange={(e) => onChange(e.target.value || null as any)}
      placeholder={placeholder}
      className="rounded-xl border-[#57715B]/20 focus:border-[#57715B]/50 bg-white/60"
    />
  );

  const checkedCount = Object.values(form.homologacao_checklist).filter(Boolean).length;

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto bg-white/95 backdrop-blur-xl border-[#57715B]/20 rounded-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-3 text-[#2D362E] font-serif text-xl">
            <div className="w-9 h-9 rounded-full bg-[#57715B]/10 flex items-center justify-center">
              <Building2 className="h-5 w-5 text-[#57715B]" />
            </div>
            {editingFornecedor ? "Editar Fornecedor" : "Novo Fornecedor"}
          </DialogTitle>
        </DialogHeader>

        <Tabs defaultValue="geral" className="mt-2">
          <TabsList className="bg-[#57715B]/8 rounded-xl w-full">
            <TabsTrigger value="geral" className="flex-1 rounded-lg data-[state=active]:bg-[#57715B] data-[state=active]:text-white text-xs font-semibold">
              Dados Gerais
            </TabsTrigger>
            <TabsTrigger value="comercial" className="flex-1 rounded-lg data-[state=active]:bg-[#57715B] data-[state=active]:text-white text-xs font-semibold">
              Comercial
            </TabsTrigger>
            <TabsTrigger value="homologacao" className="flex-1 rounded-lg data-[state=active]:bg-[#57715B] data-[state=active]:text-white text-xs font-semibold relative">
              Homologação
              <span className={cn(
                "ml-1 text-[10px] font-bold px-1 rounded-full",
                checkedCount === 5 ? "bg-emerald-500 text-white" : "bg-[#57715B]/20 text-[#57715B]"
              )}>
                {checkedCount}/5
              </span>
            </TabsTrigger>
          </TabsList>

          {/* Dados Gerais */}
          <TabsContent value="geral" className="space-y-4 mt-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Razão Social *</Label>
                {field(form.nome, (v) => setForm((p) => ({ ...p, nome: v })), "Nome do fornecedor")}
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">CNPJ *</Label>
                <Input
                  value={form.cnpj}
                  onChange={(e) => setForm((p) => ({ ...p, cnpj: formatCnpj(e.target.value) }))}
                  placeholder="00.000.000/0000-00"
                  disabled={!!editingFornecedor}
                  className="rounded-xl border-[#57715B]/20 focus:border-[#57715B]/50 bg-white/60 font-mono"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">E-mail</Label>
                {field(form.email, (v) => setForm((p) => ({ ...p, email: v })), "contato@fornecedor.com.br", "email")}
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Telefone</Label>
                {field(form.telefone, (v) => setForm((p) => ({ ...p, telefone: v })), "(61) 99999-9999")}
              </div>
            </div>

            <div className="space-y-1.5">
              <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Endereço</Label>
              {field(form.endereco, (v) => setForm((p) => ({ ...p, endereco: v })), "Rua, número, cidade - UF")}
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Responsável Comercial</Label>
                {field(form.responsavel_comercial, (v) => setForm((p) => ({ ...p, responsavel_comercial: v })), "Nome do contato")}
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Website</Label>
                {field(form.website, (v) => setForm((p) => ({ ...p, website: v })), "https://fornecedor.com.br")}
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Status</Label>
                <select
                  value={form.status}
                  onChange={(e) => setForm((p) => ({ ...p, status: e.target.value as Fornecedor["status"] }))}
                  className="w-full h-10 rounded-xl border border-[#57715B]/20 bg-white/60 px-3 text-sm text-[#2D362E] focus:outline-none focus:border-[#57715B]/50"
                >
                  <option value="em_homologacao">Em homologação</option>
                  <option value="ativo">Ativo</option>
                  <option value="inativo">Inativo</option>
                  <option value="suspenso">Suspenso</option>
                </select>
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Avaliação (1–5)</Label>
                <div className="flex items-center gap-2 h-10">
                  {[1, 2, 3, 4, 5].map((n) => (
                    <button
                      key={n}
                      type="button"
                      onClick={() => setForm((p) => ({ ...p, avaliacao_desempenho: p.avaliacao_desempenho === n ? null : n }))}
                      className="transition-transform hover:scale-110"
                    >
                      <Star className={cn(
                        "h-6 w-6",
                        (form.avaliacao_desempenho ?? 0) >= n
                          ? "fill-[#C5A065] text-[#C5A065]"
                          : "text-[#57715B]/20"
                      )} />
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <div className="space-y-1.5">
              <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Observações</Label>
              <textarea
                value={form.observacoes ?? ""}
                onChange={(e) => setForm((p) => ({ ...p, observacoes: e.target.value || null }))}
                placeholder="Notas internas sobre este fornecedor..."
                rows={3}
                className="w-full rounded-xl border border-[#57715B]/20 bg-white/60 px-3 py-2 text-sm text-[#2D362E] focus:outline-none focus:border-[#57715B]/50 resize-none"
              />
            </div>
          </TabsContent>

          {/* Comercial */}
          <TabsContent value="comercial" className="space-y-6 mt-4">
            <div className="space-y-1.5">
              <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Lead Time (dias úteis)</Label>
              <Input
                type="number"
                min={0}
                value={form.lead_time_dias_uteis ?? ""}
                onChange={(e) => setForm((p) => ({ ...p, lead_time_dias_uteis: parseInt(e.target.value) || null }))}
                placeholder="Ex: 3"
                className="w-40 rounded-xl border-[#57715B]/20 bg-white/60"
              />
            </div>

            {/* Produtos fornecidos */}
            <div className="space-y-3">
              <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Produtos Fornecidos</Label>
              {form.produtos_fornecidos.length > 0 && (
                <div className="flex flex-wrap gap-2">
                  {form.produtos_fornecidos.map((p, i) => (
                    <div key={i} className="flex items-center gap-1.5 bg-[#57715B]/8 border border-[#57715B]/15 rounded-full px-3 py-1 text-sm text-[#2D362E]">
                      <span className="font-medium">{p.nome}</span>
                      <span className="text-[#57715B]/60 text-xs">({p.unidade})</span>
                      <button type="button" onClick={() => removeProduto(i)} className="ml-1 text-[#57715B]/40 hover:text-red-500 transition-colors">
                        <Trash2 className="h-3 w-3" />
                      </button>
                    </div>
                  ))}
                </div>
              )}
              <div className="flex gap-2">
                <Input
                  value={newProduto.nome}
                  onChange={(e) => setNewProduto((p) => ({ ...p, nome: e.target.value }))}
                  placeholder="Nome do produto"
                  className="flex-1 rounded-xl border-[#57715B]/20 bg-white/60 text-sm"
                  onKeyDown={(e) => e.key === "Enter" && addProduto()}
                />
                <Input
                  value={newProduto.unidade}
                  onChange={(e) => setNewProduto((p) => ({ ...p, unidade: e.target.value }))}
                  placeholder="Unidade (ex: kg)"
                  className="w-32 rounded-xl border-[#57715B]/20 bg-white/60 text-sm"
                  onKeyDown={(e) => e.key === "Enter" && addProduto()}
                />
                <Button type="button" onClick={addProduto} size="sm" className="rounded-xl bg-[#57715B] hover:bg-[#4A614D] text-white px-3">
                  <Plus className="h-4 w-4" />
                </Button>
              </div>
            </div>

            {/* Tabela de preços */}
            <div className="space-y-3">
              <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Tabela de Preços</Label>
              {form.tabela_precos.length > 0 && (
                <div className="rounded-xl border border-[#57715B]/10 overflow-hidden">
                  <table className="w-full text-sm">
                    <thead className="bg-[#57715B]/5 text-[#57715B] text-xs font-semibold uppercase tracking-wider">
                      <tr>
                        <th className="text-left px-3 py-2">Produto</th>
                        <th className="text-left px-3 py-2">Unid.</th>
                        <th className="text-right px-3 py-2">Preço</th>
                        <th className="text-center px-3 py-2">Validade</th>
                        <th className="w-8"></th>
                      </tr>
                    </thead>
                    <tbody>
                      {form.tabela_precos.map((tp, i) => (
                        <tr key={i} className="border-t border-[#57715B]/5 hover:bg-[#57715B]/3">
                          <td className="px-3 py-2 font-medium text-[#2D362E]">{tp.produto}</td>
                          <td className="px-3 py-2 text-[#57715B]/70">{tp.unidade}</td>
                          <td className="px-3 py-2 text-right font-bold text-[#2D362E]">
                            {tp.preco.toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}
                          </td>
                          <td className="px-3 py-2 text-center text-[#57715B]/70 text-xs">
                            {tp.vigencia_ate ? new Date(tp.vigencia_ate + "T12:00:00").toLocaleDateString("pt-BR") : "—"}
                          </td>
                          <td className="px-3 py-2">
                            <button type="button" onClick={() => removePreco(i)} className="text-[#57715B]/30 hover:text-red-500 transition-colors">
                              <Trash2 className="h-3.5 w-3.5" />
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
              <div className="grid grid-cols-4 gap-2">
                <Input value={newPreco.produto} onChange={(e) => setNewPreco((p) => ({ ...p, produto: e.target.value }))} placeholder="Produto" className="col-span-2 rounded-xl border-[#57715B]/20 bg-white/60 text-sm" />
                <Input value={newPreco.unidade} onChange={(e) => setNewPreco((p) => ({ ...p, unidade: e.target.value }))} placeholder="Unid." className="rounded-xl border-[#57715B]/20 bg-white/60 text-sm" />
                <div className="flex gap-1">
                  <Input type="number" min={0} step="0.01" value={newPreco.preco} onChange={(e) => setNewPreco((p) => ({ ...p, preco: e.target.value }))} placeholder="R$" className="flex-1 rounded-xl border-[#57715B]/20 bg-white/60 text-sm" />
                </div>
                <Input type="date" value={newPreco.vigencia_ate} onChange={(e) => setNewPreco((p) => ({ ...p, vigencia_ate: e.target.value }))} className="col-span-3 rounded-xl border-[#57715B]/20 bg-white/60 text-sm" />
                <Button type="button" onClick={addPreco} size="sm" className="rounded-xl bg-[#57715B] hover:bg-[#4A614D] text-white px-3">
                  <Plus className="h-4 w-4" />
                </Button>
              </div>
            </div>
          </TabsContent>

          {/* Homologação */}
          <TabsContent value="homologacao" className="space-y-3 mt-4">
            <div className={cn(
              "rounded-2xl border p-4",
              allChecked
                ? "bg-emerald-50 border-emerald-200"
                : "bg-amber-50/60 border-amber-200/60"
            )}>
              <p className={cn(
                "text-sm font-semibold",
                allChecked ? "text-emerald-800" : "text-amber-800"
              )}>
                {allChecked
                  ? "✓ Todos os critérios cumpridos — fornecedor pode ser ativado"
                  : `${checkedCount} de 5 critérios concluídos — status permanece "Em homologação"`}
              </p>
            </div>

            <div className="space-y-2">
              {CHECKLIST_ITEMS.map(({ key, label, desc }) => {
                const checked = form.homologacao_checklist[key];
                return (
                  <button
                    key={key}
                    type="button"
                    onClick={() => toggleChecklist(key)}
                    className={cn(
                      "w-full flex items-start gap-3 rounded-xl border p-4 text-left transition-all",
                      checked
                        ? "bg-emerald-50 border-emerald-200 hover:bg-emerald-100"
                        : "bg-white/60 border-[#57715B]/15 hover:bg-[#57715B]/5"
                    )}
                  >
                    {checked
                      ? <CheckCircle2 className="h-5 w-5 text-emerald-600 mt-0.5 shrink-0" />
                      : <Circle className="h-5 w-5 text-[#57715B]/30 mt-0.5 shrink-0" />
                    }
                    <div>
                      <p className={cn("text-sm font-semibold", checked ? "text-emerald-800" : "text-[#2D362E]")}>
                        {label}
                      </p>
                      <p className="text-xs text-[#57715B]/60 mt-0.5">{desc}</p>
                    </div>
                  </button>
                );
              })}
            </div>
          </TabsContent>
        </Tabs>

        <div className="flex justify-end gap-3 pt-4 border-t border-[#57715B]/10">
          <Button variant="outline" onClick={onClose} className="rounded-xl border-[#57715B]/20">
            Cancelar
          </Button>
          <Button
            onClick={handleSave}
            disabled={saving}
            className="rounded-xl bg-[#57715B] hover:bg-[#4A614D] text-white px-6"
          >
            {saving ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
            {editingFornecedor ? "Salvar Alterações" : "Cadastrar Fornecedor"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

toolUseResult.content:
import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Label } from "@/shared/ui/label";
import { Badge } from "@/shared/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/shared/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/ui/tabs";
import {
  Building2,
  Loader2,
  Plus,
  Trash2,
  CheckCircle2,
  Circle,
  Star,
} from "lucide-react";
import { cn } from "@/shared/lib/utils";

export interface Fornecedor {
  cnpj: string;
  nome: string;
  email: string | null;
  telefone: string | null;
  endereco: string | null;
  website: string | null;
  responsavel_comercial: string | null;
  lead_time_dias_uteis: number | null;
  status: "ativo" | "em_homologacao" | "inativo" | "suspenso";
  produtos_fornecidos: { nome: string; unidade: string }[];
  tabela_precos: { produto: string; unidade: string; preco: number; vigencia_ate: string }[];
  homologacao_checklist: {
    referencias_comerciais: boolean;
    pedido_teste: boolean;
    avaliacao_qualidade: boolean;
    acordo_formalizado: boolean;
    cadastro_sistema: boolean;
  };
  avaliacao_desempenho: number | null;
  observacoes: string | null;
  homologado_em: string | null;
  created_at?: string;
  updated_at?: string;
}

const CHECKLIST_ITEMS: { key: keyof Fornecedor["homologacao_checklist"]; label: string; desc: string }[] = [
  { key: "referencias_comerciais", label: "2 referências comerciais", desc: "Solicitar e verificar referências ou histórico de fornecimento" },
  { key: "pedido_teste", label: "Pedido-teste realizado", desc: "Quantidade reduzida (20–30% da demanda habitual)" },
  { key: "avaliacao_qualidade", label: "Avaliação de qualidade", desc: "Prazo de entrega, qualidade do produto, documentação fiscal e atendimento" },
  { key: "acordo_formalizado", label: "Acordo formalizado por escrito", desc: "Preço, prazo e condições de pagamento acordados" },
  { key: "cadastro_sistema", label: "Cadastrado no sistema", desc: "Cadastro completo antes de qualquer pedido" },
];

const emptyForm = (): Omit<Fornecedor, "created_at" | "updated_at" | "homologado_em"> => ({
  cnpj: "",
  nome: "",
  email: null,
  telefone: null,
  endereco: null,
  website: null,
  responsavel_comercial: null,
  lead_time_dias_uteis: null,
  status: "em_homologacao",
  produtos_fornecidos: [],
  tabela_precos: [],
  homologacao_checklist: {
    referencias_comerciais: false,
    pedido_teste: false,
    avaliacao_qualidade: false,
    acordo_formalizado: false,
    cadastro_sistema: false,
  },
  avaliacao_desempenho: null,
  observacoes: null,
});

function formatCnpj(raw: string): string {
  const d = raw.replace(/\D/g, "").slice(0, 14);
  if (d.length <= 2) return d;
  if (d.length <= 5) return `${d.slice(0, 2)}.${d.slice(2)}`;
  if (d.length <= 8) return `${d.slice(0, 2)}.${d.slice(2, 5)}.${d.slice(5)}`;
  if (d.length <= 12) return `${d.slice(0, 2)}.${d.slice(2, 5)}.${d.slice(5, 8)}/${d.slice(8)}`;
  return `${d.slice(0, 2)}.${d.slice(2, 5)}.${d.slice(5, 8)}/${d.slice(8, 12)}-${d.slice(12)}`;
}

interface Props {
  open: boolean;
  onClose: () => void;
  editingFornecedor: Fornecedor | null;
  onSaved: () => void;
}

export const FornecedorModal = ({ open, onClose, editingFornecedor, onSaved }: Props) => {
  const [form, setForm] = useState(emptyForm());
  const [saving, setSaving] = useState(false);
  const [newProduto, setNewProduto] = useState({ nome: "", unidade: "" });
  const [newPreco, setNewPreco] = useState({ produto: "", unidade: "", preco: "", vigencia_ate: "" });

  useEffect(() => {
    if (editingFornecedor) {
      setForm({
        cnpj: editingFornecedor.cnpj,
        nome: editingFornecedor.nome,
        email: editingFornecedor.email,
        telefone: editingFornecedor.telefone,
        endereco: editingFornecedor.endereco,
        website: editingFornecedor.website,
        responsavel_comercial: editingFornecedor.responsavel_comercial,
        lead_time_dias_uteis: editingFornecedor.lead_time_dias_uteis,
        status: editingFornecedor.status,
        produtos_fornecidos: editingFornecedor.produtos_fornecidos ?? [],
        tabela_precos: editingFornecedor.tabela_precos ?? [],
        homologacao_checklist: editingFornecedor.homologacao_checklist ?? emptyForm().homologacao_checklist,
        avaliacao_desempenho: editingFornecedor.avaliacao_desempenho,
        observacoes: editingFornecedor.observacoes,
      });
    } else {
      setForm(emptyForm());
    }
  }, [editingFornecedor, open]);

  const allChecked = Object.values(form.homologacao_checklist).every(Boolean);

  const toggleChecklist = (key: keyof Fornecedor["homologacao_checklist"]) => {
    setForm((prev) => {
      const updated = { ...prev.homologacao_checklist, [key]: !prev.homologacao_checklist[key] };
      const allDone = Object.values(updated).every(Boolean);
      return {
        ...prev,
        homologacao_checklist: updated,
        status: allDone ? "ativo" : prev.status === "ativo" ? "em_homologacao" : prev.status,
      };
    });
  };

  const handleSave = async () => {
    if (!form.cnpj.replace(/\D/g, "") || !form.nome.trim()) {
      toast.error("CNPJ e Razão Social são obrigatórios.");
      return;
    }
    const cnpjDigits = form.cnpj.replace(/\D/g, "");
    if (cnpjDigits.length !== 14) {
      toast.error("CNPJ inválido — deve ter 14 dígitos.");
      return;
    }

    setSaving(true);
    try {
      const payload = {
        cnpj: cnpjDigits,
        nome: form.nome.trim(),
        email: form.email?.trim() || null,
        telefone: form.telefone?.trim() || null,
        endereco: form.endereco?.trim() || null,
        website: form.website?.trim() || null,
        responsavel_comercial: form.responsavel_comercial?.trim() || null,
        lead_time_dias_uteis: form.lead_time_dias_uteis || null,
        status: form.status,
        produtos_fornecidos: form.produtos_fornecidos,
        tabela_precos: form.tabela_precos,
        homologacao_checklist: form.homologacao_checklist,
        avaliacao_desempenho: form.avaliacao_desempenho || null,
        observacoes: form.observacoes?.trim() || null,
        ...(allChecked && !editingFornecedor?.homologado_em ? { homologado_em: new Date().toISOString() } : {}),
      };

      if (editingFornecedor) {
        const { error } = await supabase.from("fornecedores").update(payload).eq("cnpj", cnpjDigits);
        if (error) throw error;
        toast.success("Fornecedor atualizado.");
      } else {
        const { error } = await supabase.from("fornecedores").insert(payload);
        if (error) throw error;
        toast.success("Fornecedor cadastrado.");
      }

      onSaved();
      onClose();
    } catch (e: any) {
      console.error(e);
      if (e?.code === "23505") toast.error("CNPJ já cadastrado.");
      else toast.error("Erro ao salvar fornecedor.");
    } finally {
      setSaving(false);
    }
  };

  const addProduto = () => {
    if (!newProduto.nome.trim()) return;
    setForm((p) => ({ ...p, produtos_fornecidos: [...p.produtos_fornecidos, { nome: newProduto.nome.trim(), unidade: newProduto.unidade.trim() || "un" }] }));
    setNewProduto({ nome: "", unidade: "" });
  };

  const removeProduto = (i: number) => {
    setForm((p) => ({ ...p, produtos_fornecidos: p.produtos_fornecidos.filter((_, idx) => idx !== i) }));
  };

  const addPreco = () => {
    if (!newPreco.produto.trim() || !newPreco.preco) return;
    setForm((p) => ({
      ...p,
      tabela_precos: [...p.tabela_precos, {
        produto: newPreco.produto.trim(),
        unidade: newPreco.unidade.trim() || "un",
        preco: parseFloat(newPreco.preco),
        vigencia_ate: newPreco.vigencia_ate || "",
      }],
    }));
    setNewPreco({ produto: "", unidade: "", preco: "", vigencia_ate: "" });
  };

  const removePreco = (i: number) => {
    setForm((p) => ({ ...p, tabela_precos: p.tabela_precos.filter((_, idx) => idx !== i) }));
  };

  const field = (value: string | null, onChange: (v: string) => void, placeholder: string, type = "text") => (
    <Input
      type={type}
      value={value ?? ""}
      onChange={(e) => onChange(e.target.value || null as any)}
      placeholder={placeholder}
      className="rounded-xl border-[#57715B]/20 focus:border-[#57715B]/50 bg-white/60"
    />
  );

  const checkedCount = Object.values(form.homologacao_checklist).filter(Boolean).length;

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto bg-white/95 backdrop-blur-xl border-[#57715B]/20 rounded-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-3 text-[#2D362E] font-serif text-xl">
            <div className="w-9 h-9 rounded-full bg-[#57715B]/10 flex items-center justify-center">
              <Building2 className="h-5 w-5 text-[#57715B]" />
            </div>
            {editingFornecedor ? "Editar Fornecedor" : "Novo Fornecedor"}
          </DialogTitle>
        </DialogHeader>

        <Tabs defaultValue="geral" className="mt-2">
          <TabsList className="bg-[#57715B]/8 rounded-xl w-full">
            <TabsTrigger value="geral" className="flex-1 rounded-lg data-[state=active]:bg-[#57715B] data-[state=active]:text-white text-xs font-semibold">
              Dados Gerais
            </TabsTrigger>
            <TabsTrigger value="comercial" className="flex-1 rounded-lg data-[state=active]:bg-[#57715B] data-[state=active]:text-white text-xs font-semibold">
              Comercial
            </TabsTrigger>
            <TabsTrigger value="homologacao" className="flex-1 rounded-lg data-[state=active]:bg-[#57715B] data-[state=active]:text-white text-xs font-semibold relative">
              Homologação
              <span className={cn(
                "ml-1 text-[10px] font-bold px-1 rounded-full",
                checkedCount === 5 ? "bg-emerald-500 text-white" : "bg-[#57715B]/20 text-[#57715B]"
              )}>
                {checkedCount}/5
              </span>
            </TabsTrigger>
          </TabsList>

          {/* Dados Gerais */}
          <TabsContent value="geral" className="space-y-4 mt-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Razão Social *</Label>
                {field(form.nome, (v) => setForm((p) => ({ ...p, nome: v })), "Nome do fornecedor")}
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">CNPJ *</Label>
                <Input
                  value={form.cnpj}
                  onChange={(e) => setForm((p) => ({ ...p, cnpj: formatCnpj(e.target.value) }))}
                  placeholder="00.000.000/0000-00"
                  disabled={!!editingFornecedor}
                  className="rounded-xl border-[#57715B]/20 focus:border-[#57715B]/50 bg-white/60 font-mono"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">E-mail</Label>
                {field(form.email, (v) => setForm((p) => ({ ...p, email: v })), "contato@fornecedor.com.br", "email")}
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Telefone</Label>
                {field(form.telefone, (v) => setForm((p) => ({ ...p, telefone: v })), "(61) 99999-9999")}
              </div>
            </div>

            <div className="space-y-1.5">
              <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Endereço</Label>
              {field(form.endereco, (v) => setForm((p) => ({ ...p, endereco: v })), "Rua, número, cidade - UF")}
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Responsável Comercial</Label>
                {field(form.responsavel_comercial, (v) => setForm((p) => ({ ...p, responsavel_comercial: v })), "Nome do contato")}
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Website</Label>
                {field(form.website, (v) => setForm((p) => ({ ...p, website: v })), "https://fornecedor.com.br")}
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Status</Label>
                <select
                  value={form.status}
                  onChange={(e) => setForm((p) => ({ ...p, status: e.target.value as Fornecedor["status"] }))}
                  className="w-full h-10 rounded-xl border border-[#57715B]/20 bg-white/60 px-3 text-sm text-[#2D362E] focus:outline-none focus:border-[#57715B]/50"
                >
                  <option value="em_homologacao">Em homologação</option>
                  <option value="ativo">Ativo</option>
                  <option value="inativo">Inativo</option>
                  <option value="suspenso">Suspenso</option>
                </select>
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Avaliação (1–5)</Label>
                <div className="flex items-center gap-2 h-10">
                  {[1, 2, 3, 4, 5].map((n) => (
                    <button
                      key={n}
                      type="button"
                      onClick={() => setForm((p) => ({ ...p, avaliacao_desempenho: p.avaliacao_desempenho === n ? null : n }))}
                      className="transition-transform hover:scale-110"
                    >
                      <Star className={cn(
                        "h-6 w-6",
                        (form.avaliacao_desempenho ?? 0) >= n
                          ? "fill-[#C5A065] text-[#C5A065]"
                          : "text-[#57715B]/20"
                      )} />
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <div className="space-y-1.5">
              <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Observações</Label>
              <textarea
                value={form.observacoes ?? ""}
                onChange={(e) => setForm((p) => ({ ...p, observacoes: e.target.value || null }))}
                placeholder="Notas internas sobre este fornecedor..."
                rows={3}
                className="w-full rounded-xl border border-[#57715B]/20 bg-white/60 px-3 py-2 text-sm text-[#2D362E] focus:outline-none focus:border-[#57715B]/50 resize-none"
              />
            </div>
          </TabsContent>

          {/* Comercial */}
          <TabsContent value="comercial" className="space-y-6 mt-4">
            <div className="space-y-1.5">
              <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Lead Time (dias úteis)</Label>
              <Input
                type="number"
                min={0}
                value={form.lead_time_dias_uteis ?? ""}
                onChange={(e) => setForm((p) => ({ ...p, lead_time_dias_uteis: parseInt(e.target.value) || null }))}
                placeholder="Ex: 3"
                className="w-40 rounded-xl border-[#57715B]/20 bg-white/60"
              />
            </div>

            {/* Produtos fornecidos */}
            <div className="space-y-3">
              <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Produtos Fornecidos</Label>
              {form.produtos_fornecidos.length > 0 && (
                <div className="flex flex-wrap gap-2">
                  {form.produtos_fornecidos.map((p, i) => (
                    <div key={i} className="flex items-center gap-1.5 bg-[#57715B]/8 border border-[#57715B]/15 rounded-full px-3 py-1 text-sm text-[#2D362E]">
                      <span className="font-medium">{p.nome}</span>
                      <span className="text-[#57715B]/60 text-xs">({p.unidade})</span>
                      <button type="button" onClick={() => removeProduto(i)} className="ml-1 text-[#57715B]/40 hover:text-red-500 transition-colors">
                        <Trash2 className="h-3 w-3" />
                      </button>
                    </div>
                  ))}
                </div>
              )}
              <div className="flex gap-2">
                <Input
                  value={newProduto.nome}
                  onChange={(e) => setNewProduto((p) => ({ ...p, nome: e.target.value }))}
                  placeholder="Nome do produto"
                  className="flex-1 rounded-xl border-[#57715B]/20 bg-white/60 text-sm"
                  onKeyDown={(e) => e.key === "Enter" && addProduto()}
                />
                <Input
                  value={newProduto.unidade}
                  onChange={(e) => setNewProduto((p) => ({ ...p, unidade: e.target.value }))}
                  placeholder="Unidade (ex: kg)"
                  className="w-32 rounded-xl border-[#57715B]/20 bg-white/60 text-sm"
                  onKeyDown={(e) => e.key === "Enter" && addProduto()}
                />
                <Button type="button" onClick={addProduto} size="sm" className="rounded-xl bg-[#57715B] hover:bg-[#4A614D] text-white px-3">
                  <Plus className="h-4 w-4" />
                </Button>
              </div>
            </div>

            {/* Tabela de preços */}
            <div className="space-y-3">
              <Label className="text-xs font-semibold text-[#57715B] uppercase tracking-wider">Tabela de Preços</Label>
              {form.tabela_precos.length > 0 && (
                <div className="rounded-xl border border-[#57715B]/10 overflow-hidden">
                  <table className="w-full text-sm">
                    <thead className="bg-[#57715B]/5 text-[#57715B] text-xs font-semibold uppercase tracking-wider">
                      <tr>
                        <th className="text-left px-3 py-2">Produto</th>
                        <th className="text-left px-3 py-2">Unid.</th>
                        <th className="text-right px-3 py-2">Preço</th>
                        <th className="text-center px-3 py-2">Validade</th>
                        <th className="w-8"></th>
                      </tr>
                    </thead>
                    <tbody>
                      {form.tabela_precos.map((tp, i) => (
                        <tr key={i} className="border-t border-[#57715B]/5 hover:bg-[#57715B]/3">
                          <td className="px-3 py-2 font-medium text-[#2D362E]">{tp.produto}</td>
                          <td className="px-3 py-2 text-[#57715B]/70">{tp.unidade}</td>
                          <td className="px-3 py-2 text-right font-bold text-[#2D362E]">
                            {tp.preco.toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}
                          </td>
                          <td className="px-3 py-2 text-center text-[#57715B]/70 text-xs">
                            {tp.vigencia_ate ? new Date(tp.vigencia_ate + "T12:00:00").toLocaleDateString("pt-BR") : "—"}
                          </td>
                          <td className="px-3 py-2">
                            <button type="button" onClick={() => removePreco(i)} className="text-[#57715B]/30 hover:text-red-500 transition-colors">
                              <Trash2 className="h-3.5 w-3.5" />
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
              <div className="grid grid-cols-4 gap-2">
                <Input value={newPreco.produto} onChange={(e) => setNewPreco((p) => ({ ...p, produto: e.target.value }))} placeholder="Produto" className="col-span-2 rounded-xl border-[#57715B]/20 bg-white/60 text-sm" />
                <Input value={newPreco.unidade} onChange={(e) => setNewPreco((p) => ({ ...p, unidade: e.target.value }))} placeholder="Unid." className="rounded-xl border-[#57715B]/20 bg-white/60 text-sm" />
                <div className="flex gap-1">
                  <Input type="number" min={0} step="0.01" value={newPreco.preco} onChange={(e) => setNewPreco((p) => ({ ...p, preco: e.target.value }))} placeholder="R$" className="flex-1 rounded-xl border-[#57715B]/20 bg-white/60 text-sm" />
                </div>
                <Input type="date" value={newPreco.vigencia_ate} onChange={(e) => setNewPreco((p) => ({ ...p, vigencia_ate: e.target.value }))} className="col-span-3 rounded-xl border-[#57715B]/20 bg-white/60 text-sm" />
                <Button type="button" onClick={addPreco} size="sm" className="rounded-xl bg-[#57715B] hover:bg-[#4A614D] text-white px-3">
                  <Plus className="h-4 w-4" />
                </Button>
              </div>
            </div>
          </TabsContent>

          {/* Homologação */}
          <TabsContent value="homologacao" className="space-y-3 mt-4">
            <div className={cn(
              "rounded-2xl border p-4",
              allChecked
                ? "bg-emerald-50 border-emerald-200"
                : "bg-amber-50/60 border-amber-200/60"
            )}>
              <p className={cn(
                "text-sm font-semibold",
                allChecked ? "text-emerald-800" : "text-amber-800"
              )}>
                {allChecked
                  ? "✓ Todos os critérios cumpridos — fornecedor pode ser ativado"
                  : `${checkedCount} de 5 critérios concluídos — status permanece "Em homologação"`}
              </p>
            </div>

            <div className="space-y-2">
              {CHECKLIST_ITEMS.map(({ key, label, desc }) => {
                const checked = form.homologacao_checklist[key];
                return (
                  <button
                    key={key}
                    type="button"
                    onClick={() => toggleChecklist(key)}
                    className={cn(
                      "w-full flex items-start gap-3 rounded-xl border p-4 text-left transition-all",
                      checked
                        ? "bg-emerald-50 border-emerald-200 hover:bg-emerald-100"
                        : "bg-white/60 border-[#57715B]/15 hover:bg-[#57715B]/5"
                    )}
                  >
                    {checked
                      ? <CheckCircle2 className="h-5 w-5 text-emerald-600 mt-0.5 shrink-0" />
                      : <Circle className="h-5 w-5 text-[#57715B]/30 mt-0.5 shrink-0" />
                    }
                    <div>
                      <p className={cn("text-sm font-semibold", checked ? "text-emerald-800" : "text-[#2D362E]")}>
                        {label}
                      </p>
                      <p className="text-xs text-[#57715B]/60 mt-0.5">{desc}</p>
                    </div>
                  </button>
                );
              })}
            </div>
          </TabsContent>
        </Tabs>

        <div className="flex justify-end gap-3 pt-4 border-t border-[#57715B]/10">
          <Button variant="outline" onClick={onClose} className="rounded-xl border-[#57715B]/20">
            Cancelar
          </Button>
          <Button
            onClick={handleSave}
            disabled={saving}
            className="rounded-xl bg-[#57715B] hover:bg-[#4A614D] text-white px-6"
          >
            {saving ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
            {editingFornecedor ? "Salvar Alterações" : "Cadastrar Fornecedor"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

input.content:
import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Badge } from "@/shared/ui/badge";
import { GlassCard } from "@/shared/ui/glass-card";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/shared/ui/table";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/ui/alert-dialog";
import {
  Building2, Search, Plus, Pencil, Trash2, Loader2,
  Star, Clock, Phone, Mail, Globe, CheckCircle2, Circle,
  Users, ShieldCheck, AlertTriangle,
} from "lucide-react";
import { cn } from "@/shared/lib/utils";
import { FornecedorModal, Fornecedor } from "./FornecedorModal";

function formatCnpj(cnpj: string | null): string {
  if (!cnpj) return "—";
  const d = cnpj.replace(/\D/g, "");
  if (d.length !== 14) return cnpj;
  return `${d.slice(0, 2)}.${d.slice(2, 5)}.${d.slice(5, 8)}/${d.slice(8, 12)}-${d.slice(12)}`;
}

const STATUS_CONFIG: Record<Fornecedor["status"], { label: string; cls: string; icon: React.ReactNode }> = {
  ativo: {
    label: "Ativo",
    cls: "bg-emerald-100 text-emerald-800 border-emerald-200",
    icon: <CheckCircle2 className="h-3 w-3" />,
  },
  em_homologacao: {
    label: "Em homologação",
    cls: "bg-amber-100 text-amber-800 border-amber-200",
    icon: <ShieldCheck className="h-3 w-3" />,
  },
  inativo: {
    label: "Inativo",
    cls: "bg-gray-100 text-gray-600 border-gray-200",
    icon: <Circle className="h-3 w-3" />,
  },
  suspenso: {
    label: "Suspenso",
    cls: "bg-red-100 text-red-700 border-red-200",
    icon: <AlertTriangle className="h-3 w-3" />,
  },
};

const STATUS_FILTERS = [
  { value: "all", label: "Todos" },
  { value: "ativo", label: "Ativos" },
  { value: "em_homologacao", label: "Em homologação" },
  { value: "inativo", label: "Inativos" },
  { value: "suspenso", label: "Suspensos" },
] as const;

export const FornecedoresGestao = () => {
  const [fornecedores, setFornecedores] = useState<Fornecedor[]>([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [modalOpen, setModalOpen] = useState(false);
  const [editingFornecedor, setEditingFornecedor] = useState<Fornecedor | null>(null);
  const [deletingCnpj, setDeletingCnpj] = useState<string | null>(null);
  const [deleting, setDeleting] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("fornecedores")
        .select("*")
        .order("nome");
      if (error) throw error;
      setFornecedores((data || []) as Fornecedor[]);
    } catch {
      toast.error("Erro ao carregar fornecedores.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const filtered = fornecedores.filter((f) => {
    if (statusFilter !== "all" && f.status !== statusFilter) return false;
    if (!search.trim()) return true;
    const q = search.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");
    const hay = [f.nome, f.cnpj, f.email ?? "", f.telefone ?? "", f.responsavel_comercial ?? ""]
      .join(" ").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");
    return hay.includes(q);
  });

  const handleDelete = async () => {
    if (!deletingCnpj) return;
    setDeleting(true);
    try {
      const { error } = await supabase.from("fornecedores").delete().eq("cnpj", deletingCnpj);
      if (error) throw error;
      toast.success("Fornecedor removido.");
      setDeletingCnpj(null);
      load();
    } catch {
      toast.error("Erro ao remover fornecedor.");
    } finally {
      setDeleting(false);
    }
  };

  const counts = {
    ativo: fornecedores.filter((f) => f.status === "ativo").length,
    em_homologacao: fornecedores.filter((f) => f.status === "em_homologacao").length,
    inativo: fornecedores.filter((f) => f.status === "inativo").length,
  };

  const checkedCount = (f: Fornecedor) =>
    Object.values(f.homologacao_checklist ?? {}).filter(Boolean).length;

  return (
    <div className="space-y-4">
      {/* KPIs */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {[
          { label: "Total", value: fornecedores.length, icon: <Users className="h-4 w-4" />, color: "text-[#57715B]", bg: "bg-[#57715B]/10" },
          { label: "Ativos", value: counts.ativo, icon: <CheckCircle2 className="h-4 w-4" />, color: "text-emerald-700", bg: "bg-emerald-100" },
          { label: "Em homologação", value: counts.em_homologacao, icon: <ShieldCheck className="h-4 w-4" />, color: "text-amber-700", bg: "bg-amber-100" },
          { label: "Inativos", value: counts.inativo, icon: <Circle className="h-4 w-4" />, color: "text-gray-500", bg: "bg-gray-100" },
        ].map((k) => (
          <GlassCard key={k.label} className="p-4">
            <div className="flex items-center gap-3">
              <div className={cn("w-9 h-9 rounded-full flex items-center justify-center shrink-0", k.bg)}>
                <span className={k.color}>{k.icon}</span>
              </div>
              <div>
                <p className="text-2xl font-bold text-[#2D362E]">{k.value}</p>
                <p className="text-xs text-[#57715B]/70">{k.label}</p>
              </div>
            </div>
          </GlassCard>
        ))}
      </div>

      {/* Header + filters */}
      <GlassCard className="p-4 sm:p-5">
        <div className="flex flex-col sm:flex-row sm:items-center gap-3">
          <div className="flex items-center gap-3 flex-1">
            <div className="w-10 h-10 rounded-full bg-[#57715B]/10 flex items-center justify-center shrink-0">
              <Building2 className="h-5 w-5 text-[#57715B]" />
            </div>
            <div>
              <h2 className="text-lg font-serif font-bold text-[#2D362E]">Fornecedores</h2>
              <p className="text-xs text-[#57715B]/70">{filtered.length} {filtered.length === 1 ? "fornecedor" : "fornecedores"}</p>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row gap-2 sm:items-center">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-[#57715B]/40" />
              <Input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Buscar por nome, CNPJ..."
                className="pl-9 rounded-full border-[#57715B]/20 w-full sm:w-64"
              />
            </div>
            <Button
              onClick={() => { setEditingFornecedor(null); setModalOpen(true); }}
              className="rounded-full bg-[#57715B] hover:bg-[#4A614D] text-white shadow-md shadow-[#57715B]/20 h-10 px-5"
            >
              <Plus className="h-4 w-4 mr-2" />
              Novo Fornecedor
            </Button>
          </div>
        </div>

        {/* Status filter pills */}
        <div className="flex gap-1.5 flex-wrap mt-3 pt-3 border-t border-[#57715B]/8">
          {STATUS_FILTERS.map((sf) => (
            <button
              key={sf.value}
              onClick={() => setStatusFilter(sf.value)}
              className={cn(
                "rounded-full text-xs font-semibold px-3 py-1.5 border transition-all",
                statusFilter === sf.value
                  ? "bg-[#57715B] text-white border-[#57715B]"
                  : "text-[#57715B] border-[#57715B]/20 hover:bg-[#57715B]/8 bg-white/60"
              )}
            >
              {sf.label}
            </button>
          ))}
        </div>
      </GlassCard>

      {/* Table */}
      <GlassCard className="p-0 overflow-hidden">
        <div className="overflow-x-auto">
          <Table className="min-w-[800px] w-full text-sm">
            <TableHeader className="bg-[#57715B]/5">
              <TableRow className="hover:bg-transparent border-b border-[#57715B]/10">
                <TableHead className="font-bold text-[#57715B] uppercase text-xs tracking-wider pl-5">Fornecedor</TableHead>
                <TableHead className="w-[160px] font-bold text-[#57715B] uppercase text-xs tracking-wider">CNPJ</TableHead>
                <TableHead className="font-bold text-[#57715B] uppercase text-xs tracking-wider">Contato</TableHead>
                <TableHead className="w-[100px] font-bold text-[#57715B] uppercase text-xs tracking-wider text-center">Lead Time</TableHead>
                <TableHead className="w-[130px] font-bold text-[#57715B] uppercase text-xs tracking-wider text-center">Homologação</TableHead>
                <TableHead className="w-[140px] font-bold text-[#57715B] uppercase text-xs tracking-wider text-center">Status</TableHead>
                <TableHead className="w-[90px] font-bold text-[#57715B] uppercase text-xs tracking-wider text-center">Avaliação</TableHead>
                <TableHead className="w-[90px]"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading && (
                <TableRow>
                  <TableCell colSpan={8} className="h-32 text-center text-muted-foreground">
                    <Loader2 className="inline h-5 w-5 animate-spin mr-2" />
                    Carregando...
                  </TableCell>
                </TableRow>
              )}
              {!loading && filtered.length === 0 && (
                <TableRow>
                  <TableCell colSpan={8} className="h-32 text-center">
                    <div className="flex flex-col items-center gap-2 text-[#57715B]/50">
                      <Building2 className="h-8 w-8" />
                      <p className="text-sm">
                        {fornecedores.length === 0
                          ? "Nenhum fornecedor cadastrado. Clique em \"Novo Fornecedor\" para começar."
                          : "Nenhum fornecedor encontrado com os filtros aplicados."}
                      </p>
                    </div>
                  </TableCell>
                </TableRow>
              )}
              {!loading && filtered.map((f) => {
                const cfg = STATUS_CONFIG[f.status];
                const cc = checkedCount(f);
                return (
                  <TableRow
                    key={f.cnpj}
                    className="hover:bg-[#57715B]/4 transition-colors border-b border-[#57715B]/5"
                  >
                    {/* Nome */}
                    <TableCell className="pl-5">
                      <div className="flex flex-col">
                        <span className="font-semibold text-[#2D362E]">{f.nome}</span>
                        {f.responsavel_comercial && (
                          <span className="text-[10px] text-[#57715B]/60 flex items-center gap-1 mt-0.5">
                            <Users className="h-2.5 w-2.5" />
                            {f.responsavel_comercial}
                          </span>
                        )}
                        {(f.produtos_fornecidos?.length ?? 0) > 0 && (
                          <div className="flex flex-wrap gap-1 mt-1">
                            {f.produtos_fornecidos.slice(0, 3).map((p, i) => (
                              <span key={i} className="text-[10px] bg-[#57715B]/8 text-[#57715B] rounded-full px-2 py-0.5">
                                {p.nome}
                              </span>
                            ))}
                            {f.produtos_fornecidos.length > 3 && (
                              <span className="text-[10px] text-[#57715B]/50">+{f.produtos_fornecidos.length - 3}</span>
                            )}
                          </div>
                        )}
                      </div>
                    </TableCell>

                    {/* CNPJ */}
                    <TableCell className="font-mono text-xs text-[#2D362E]/70">
                      {formatCnpj(f.cnpj)}
                    </TableCell>

                    {/* Contato */}
                    <TableCell>
                      <div className="space-y-1">
                        {f.telefone && (
                          <div className="flex items-center gap-1.5 text-xs text-[#2D362E]/70">
                            <Phone className="h-3 w-3 text-[#57715B]/50" />
                            {f.telefone}
                          </div>
                        )}
                        {f.email && (
                          <div className="flex items-center gap-1.5 text-xs text-[#2D362E]/70">
                            <Mail className="h-3 w-3 text-[#57715B]/50" />
                            <span className="truncate max-w-[180px]">{f.email}</span>
                          </div>
                        )}
                        {f.website && (
                          <div className="flex items-center gap-1.5 text-xs text-[#57715B]/60">
                            <Globe className="h-3 w-3 text-[#57715B]/40" />
                            <span className="truncate max-w-[180px]">{f.website}</span>
                          </div>
                        )}
                        {!f.telefone && !f.email && (
                          <span className="text-xs text-[#57715B]/30 italic">Sem contato</span>
                        )}
                      </div>
                    </TableCell>

                    {/* Lead Time */}
                    <TableCell className="text-center">
                      {f.lead_time_dias_uteis != null ? (
                        <div className="flex items-center justify-center gap-1 text-sm font-semibold text-[#2D362E]">
                          <Clock className="h-3.5 w-3.5 text-[#57715B]/60" />
                          {f.lead_time_dias_uteis}d
                        </div>
                      ) : (
                        <span className="text-xs text-[#57715B]/30">—</span>
                      )}
                    </TableCell>

                    {/* Homologação checklist */}
                    <TableCell className="text-center">
                      <div className="flex items-center justify-center gap-1.5">
                        <div className="flex gap-0.5">
                          {[0, 1, 2, 3, 4].map((i) => (
                            <div
                              key={i}
                              className={cn(
                                "w-2 h-2 rounded-full",
                                i < cc ? "bg-emerald-500" : "bg-[#57715B]/15"
                              )}
                            />
                          ))}
                        </div>
                        <span className="text-xs font-semibold text-[#57715B]/70">{cc}/5</span>
                      </div>
                    </TableCell>

                    {/* Status */}
                    <TableCell className="text-center">
                      <Badge className={cn("flex items-center gap-1 justify-center text-xs font-semibold border", cfg.cls)}>
                        {cfg.icon}
                        {cfg.label}
                      </Badge>
                    </TableCell>

                    {/* Avaliação */}
                    <TableCell className="text-center">
                      {f.avaliacao_desempenho != null ? (
                        <div className="flex items-center justify-center gap-0.5">
                          <Star className="h-3.5 w-3.5 fill-[#C5A065] text-[#C5A065]" />
                          <span className="text-sm font-bold text-[#2D362E]">{f.avaliacao_desempenho}</span>
                        </div>
                      ) : (
                        <span className="text-xs text-[#57715B]/30">—</span>
                      )}
                    </TableCell>

                    {/* Actions */}
                    <TableCell className="text-center">
                      <div className="flex items-center justify-center gap-1">
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => { setEditingFornecedor(f); setModalOpen(true); }}
                          className="h-8 w-8 p-0 rounded-lg hover:bg-[#57715B]/10 text-[#57715B]"
                        >
                          <Pencil className="h-3.5 w-3.5" />
                        </Button>
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => setDeletingCnpj(f.cnpj)}
                          className="h-8 w-8 p-0 rounded-lg hover:bg-red-50 text-red-400 hover:text-red-600"
                        >
                          <Trash2 className="h-3.5 w-3.5" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </div>
      </GlassCard>

      {/* Create/Edit modal */}
      <FornecedorModal
        open={modalOpen}
        onClose={() => { setModalOpen(false); setEditingFornecedor(null); }}
        editingFornecedor={editingFornecedor}
        onSaved={load}
      />

      {/* Delete confirm */}
      <AlertDialog open={!!deletingCnpj} onOpenChange={(v) => !v && setDeletingCnpj(null)}>
        <AlertDialogContent className="rounded-2xl border-[#57715B]/20">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-[#2D362E]">Remover fornecedor?</AlertDialogTitle>
            <AlertDialogDescription className="text-[#57715B]/70">
              Esta ação é irreversível. O fornecedor será removido do cadastro, mas suas notas fiscais já lançadas não serão afetadas.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="rounded-xl">Cancelar</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              disabled={deleting}
              className="rounded-xl bg-red-600 hover:bg-red-700 text-white"
            >
              {deleting ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
              Remover
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};

