-- Constraint: valid status values
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'fornecedores_status_check'
      AND conrelid = 'public.fornecedores'::regclass
  ) THEN
    ALTER TABLE public.fornecedores
      ADD CONSTRAINT fornecedores_status_check
      CHECK (status IN ('ativo', 'em_homologacao', 'inativo', 'suspenso'));
  END IF;
END $$;

